<?php

namespace wcf\system\worker;

use wcf\command\file\CreateFileFromExistingFile;
use wcf\data\media\Media;
use wcf\data\media\MediaBuilder;
use wcf\data\media\MediaList;
use wcf\system\WCF;

use function wcf\functions\exception\logThrowable;

/**
 * Worker implementation for migrating media files to the new upload API.
 *
 * The thumbnails of migrated media files are generated by the
 * `FileRebuildDataWorker`.
 *
 * @author  Alexander Ebert, Marcel Werk
 * @copyright   2001-2026 WoltLab GmbH
 * @license GNU Lesser General Public License <http://opensource.org/licenses/lgpl-license.php>
 *
 * @extends AbstractLinearRebuildDataWorker<MediaList>
 */
class MediaRebuildDataWorker extends AbstractLinearRebuildDataWorker
{
    /**
     * @inheritDoc
     */
    protected $objectListClassName = MediaList::class;

    /**
     * @inheritDoc
     */
    protected $limit = 50;

    #[\Override]
    public function execute()
    {
        parent::execute();

        foreach ($this->objectList as $media) {
            if ($media->fileID !== null) {
                continue;
            }

            $this->migrate($media);
        }
    }

    private function migrate(Media $media): void
    {
        $file = new CreateFileFromExistingFile(
            $media->getLocation(),
            $media->filename,
            'com.woltlab.wcf.media',
            uploadTime: $media->uploadTime ?: null,
        )();

        if ($file === null) {
            // Media files are referenced by content, therefore a missing
            // physical file must not remove the media file silently.
            logThrowable(new \RuntimeException(
                "Unable to migrate the media file '{$media->mediaID}', its physical file is missing."
            ));

            return;
        }

        // The physical file has been moved, the media file must reference the
        // new file immediately to not lose track of it.
        $sql = "UPDATE  wcf1_media
                SET     fileID = ?
                WHERE   mediaID = ?";
        $statement = WCF::getDB()->prepare($sql);
        $statement->execute([
            $file->fileID,
            $media->mediaID,
        ]);

        // The denormalized meta data is updated from the actual file, because
        // the rotation of images may have been normalized.
        MediaBuilder::forUpdate(new Media($media->mediaID))
            ->setFile($file)
            ->update();

        $this->deleteLegacyThumbnails($media);
    }

    private function deleteLegacyThumbnails(Media $media): void
    {
        if ($media->isImage === 0) {
            return;
        }

        foreach (\array_keys(Media::getThumbnailSizes()) as $size) {
            $location = $media->getThumbnailLocation($size);
            if (\file_exists($location)) {
                @\unlink($location);
            }
        }
    }
}
